#### release(reservationId: string): Promise<ReleaseOutcome>
- If id is not a valid UUID or no reservation → UNKNOWN_RESERVATION.
- If reservation is already released → ALREADY_RELEASED.
- If active → release it: set state to released, add release ledger entries (delta = +quantity per line), update stock (reserved -= quantity).

```ts
export async function release(reservationId: string): Promise<ReleaseOutcome> {
  // validate UUID format
  if (!isValidUUID(reservationId)) {
    return { status: "rejected", reason: "UNKNOWN_RESERVATION", details: [] };
  }
  return await client.transaction(async (tx) => {
    const res = await tx.querySingle(`select default::Reservation { id, state, lines: { item: { sku }, quantity } } filter .id = <uuid>$rid`, { rid: reservationId });
    if (!res) {
      return { status: "rejected", reason: "UNKNOWN_RESERVATION", details: [] };
    }
    if (res.state === "released") {
      return { status: "rejected", reason: "ALREADY_RELEASED", details: [] };
    }
    // release: for each line, update stock, add ledger entry
    for (const line of res.lines) {
      await tx.execute(`update default::StockItem filter .sku = <str>$sku set { reserved := .reserved - <int64>$qty }`, { sku: line.item.sku, qty: line.quantity });
      await tx.execute(`insert default::LedgerEntry { reservation := (select default::Reservation filter .id = <uuid>$rid), item := (select default::StockItem filter .sku = <str>$sku), delta := <int64>$qty, kind := default::LedgerKind.release }`, { rid: reservationId, sku: line.item.sku, qty: line.quantity });
    }
    await tx.execute(`update default::Reservation filter .id = <uuid>$rid set { state := default::State.released }`, { rid: reservationId });
    return { status: "released", reservationId: reservationId };
  });
}
```

