```ts
export async function expireDue(now: string): Promise<{released: string[]}> {
  const nowDate = new Date(now);
  return await client.transaction(async (tx) => {
    const due = await tx.query(`select default::Reservation { id, lines: { item: { sku }, quantity } } filter .state = default::State.active and .expiresAt != null and .expiresAt <= <datetime>$now order by .id`, { now: nowDate });
    const releasedIds = [];
    for (const res of due) {
      for (const line of res.lines) {
        await tx.execute(`update default::StockItem filter .sku = <str>$sku set { reserved := .reserved - <int64>$qty }`, { sku: line.item.sku, qty: line.quantity });
        await tx.execute(`insert default::LedgerEntry { reservation := (select default::Reservation filter .id = <uuid>$rid), item := (select default::StockItem filter .sku = <str>$sku), delta := <int64>$qty, kind := default::LedgerKind.release }`, { rid: res.id, sku: line.item.sku, qty: line.quantity });
      }
      await tx.execute(`update default::Reservation filter .id = <uuid>$rid set { state := default::State.released }`, { rid: res.id });
      releasedIds.push(res.id);
    }
    return { released: releasedIds.sort() };
  });
}
